import pandas as pd
import numpy as np

def r_as_data_frame(x, row_names=None, optional=False, *args, nm=None, **kwargs):
    """
    Convert input to a data frame.

    Parameters:
    - x: input object to convert
    - row_names: optional row names (character or integer vector)
    - optional: if True, don't set column names
    - nm: name for the column (default: derived from variable name)
    - **kwargs: additional arguments (ignored)

    Returns:
    - pandas DataFrame
    """

    # Handle the input x
    if isinstance(x, pd.DataFrame):
        df = x.copy()
    elif isinstance(x, dict):
        df = pd.DataFrame(x)
    elif isinstance(x, list):
        # If it's a list, convert to DataFrame with appropriate structure
        if len(x) == 0:
            df = pd.DataFrame()
        elif isinstance(x[0], (list, np.ndarray)):
            # List of lists/arrays
            df = pd.DataFrame(x)
        else:
            # Simple list - convert to single column if optional=True, else keep as is
            if optional:
                # Return as a list-like structure (single unnamed column)
                df = pd.DataFrame(x)
            else:
                df = pd.DataFrame({0: x})
    elif isinstance(x, np.ndarray):
        if x.ndim == 1:
            # 1D array becomes single column
            df = pd.DataFrame(x)
        else:
            # 2D array becomes DataFrame
            df = pd.DataFrame(x)
    elif isinstance(x, (int, float, str, bool, np.number)):
        # Scalar value - wrap in list then DataFrame
        df = pd.DataFrame([x])
    else:
        # Try to convert directly
        df = pd.DataFrame(x)

    nrows = len(df)

    # Handle row names
    if row_names is None:
        if nrows == 0:
            row_names = []
        else:
            # Default: integer sequence 1-based
            row_names = list(range(1, nrows + 1))
    elif isinstance(row_names, np.ndarray):
        row_names = row_names.tolist()
    elif not isinstance(row_names, list):
        row_names = list(row_names)

    # Validate row_names
    if len(row_names) != nrows:
        raise ValueError(f"'row.names' is not a character or integer vector of length {nrows}")

    # Set row names (index)
    df.index = row_names
    df.index.name = None

    # Handle column names
    if not optional:
        # Set column names based on nm
        if nm is not None:
            if len(df.columns) == 1:
                df.columns = [nm]
        else:
            # If no nm provided and optional=False, generate default names if needed
            if all(isinstance(col, (int, np.integer)) for col in df.columns):
                df.columns = [f"V{i+1}" for i in range(len(df.columns))]

    # If optional=True, keep columns as unnamed (numeric indices or existing names)

    return df
